// AUTO-GENERATED by Bloxks — do not edit. Overwritten on every build.
// Cross-platform icon: SF Symbol on iOS, Ionicons on Android (and in the web
// preview, which approximates SF Symbols anyway). Both props are REQUIRED so
// every icon renders on both platforms — never import SymbolView directly.
import { SymbolView, type SymbolViewProps } from 'expo-symbols'
import { Ionicons } from '@expo/vector-icons'
import type { ComponentProps } from 'react'

export type IconProps = {
  /** SF Symbol name (iOS), e.g. "house.fill". */
  name: SymbolViewProps['name']
  /** Ionicons name (Android), e.g. "home". */
  android: ComponentProps<typeof Ionicons>['name']
  size?: number
  color?: string
}

export function Icon({ name, android, size = 24, color = '#111' }: IconProps) {
  return (
    <SymbolView
      name={name}
      tintColor={color}
      style={{ width: size, height: size }}
      fallback={<Ionicons name={android} size={size} color={color} />}
    />
  )
}
